mapper.select:
select count(*)
from wf_attachment
where attachment_status = #{status}

mapper.update:
update wf_attachment set attachment_status = case when attachment_status = 'TEMP' then 'EXPIRED' else attachment_status end, cleanup_claim_token = #{claimToken}, cleanup_lease_until = timestampadd(second, #{leaseSeconds}, current_timestamp(3)), update_time = current_timestamp(3) where attachment_id in
#{attachmentId}
and storage_deleted_time is null and attachment_status in ('TEMP', 'EXPIRED', 'DELETED') and (cleanup_claim_token is null or cleanup_lease_until <= current_timestamp(3))

mapper.select:
select attachment_id from wf_attachment
where storage_deleted_time is not null and storage_deleted_time <= #{cutoffTime}
order by storage_deleted_time,attachment_id limit #{limit} for update skip locked

mapper.delete:
delete from wf_attachment where attachment_id in
#{attachmentId}
  and storage_deleted_time is not null and storage_deleted_time <= #{cutoffTime}
